// CommandHander runs the `{{.Identifier}}` command. entries is the typed view
// of the parsed argv, generated by `agnos build` from entries.yaml.
//
// This is a scaffold created by `agnos add-command` — replace the body with
// the command's real logic. If the logic should also be reusable as library
// API, add sandbox/internal/actions/{{.Package}}/ and register it in
// sandbox/binds/actions.go + sandbox/api/actions.go.
func CommandHander(deps *deps.Deps, entries *Entries) int {
	deps.Std.Printf("{{.Identifier}} called with path %s\n", entries.Path)
	return api.ExitOk
}
